-- Grounded content for the three game_content_bank games (Sentence
-- Scramble, Grammar Battle, Word Detective): 100 validated items each,
-- replacing the old ~106 pre-grounding draft rows.
--
-- Grounding discipline (session-long process, not a batch generation):
-- every item uses ONLY the 15 grammar points explicitly confirmed as
-- already taught within Lessons 1-100 (to be, basic pronouns, present
-- simple, plurals, there is/are, simple future, imperatives, basic
-- questions, can-for-ability, prepositions, past simple regular/
-- irregular, present continuous, comparatives/superlatives, first
-- conditional). No item anywhere - blank, correction, or surrounding
-- text - uses ungrounded grammar (was/were, should/must/might, present
-- perfect, passive, relative clauses, second conditional all excluded).
--
-- Five cognitive-complexity stages (very_easy/easy/medium/hard/very_hard)
-- replace the old three-tier easy/medium/hard scale. Difficulty comes
-- from complexity and combination of KNOWN grammar, never from
-- introducing grammar a student hasn't reached - e.g. very_hard uses
-- multi-clause first-conditional combinations, not second conditional.
--
-- min_lesson_number gives every item real curriculum provenance: the
-- highest lesson number among the grammar points it uses (a combined
-- item is gated by its latest component). This column is NOT YET
-- enforced by the round-selection RPCs (get_sentence_scramble_round(),
-- get_word_detective_round(), get_grammar_battle_round() still do a
-- plain random pick) - that filtering, plus difficulty-stage selection,
-- is deliberately deferred to a separate migration so this one stays a
-- pure content+schema change, reviewable and revertible on its own.
--
-- Word Detective content was rebuilt once already within this same
-- session after a mechanical cross-game overlap check found ~94 of its
-- first 100 items were near-duplicates of Sentence Scramble sentences
-- (not the ~5 initially estimated) - the current 100 are the rewritten,
-- independently-scripted set, re-verified to bring that down to 9
-- residual low-similarity overlaps (comparable to the 13 that already
-- exist, unremarkably, between Sentence Scramble and Grammar Battle).
--
-- Every wrong_index value in Word Detective was computed programmatically
-- against the actual frontend tokenization
-- (sentence.replace(/[.?!]$/, '').split(' ')) rather than hand-counted -
-- manual counting had already produced 11 wrong indices earlier in this
-- session's review process.

-- Widen the difficulty check from the old 3-tier scale to the 5 stages
-- above. Unnamed inline check constraints get an auto-generated name
-- (Postgres default: <table>_<column>_check).
alter table public.game_content_bank
  drop constraint if exists game_content_bank_difficulty_check;

alter table public.game_content_bank
  add constraint game_content_bank_difficulty_check
  check (difficulty in ('very_easy', 'easy', 'medium', 'hard', 'very_hard'));

-- Curriculum provenance: the highest lesson number required by any
-- grammar point an item uses. Nullable - existing rows in other game
-- types (grammar_battle/sentence_scramble/word_detective rows inserted
-- below all populate it; this column has no meaning for other
-- game_content_bank consumers, of which there are currently none).
alter table public.game_content_bank
  add column if not exists min_lesson_number integer;

-- Replace the old pre-grounding draft content entirely - not deleting
-- student data, just the game's own draft question/sentence bank for
-- these three game types (24 sentence_scramble + 40 grammar_battle + 42
-- word_detective rows, all authored before the confirmed-grammar rule
-- existed).
delete from public.game_content_bank
where game_type in ('sentence_scramble', 'grammar_battle', 'word_detective');

